1273	\begin{lemma}[Direct sums give product distributions]\label{lem:cl-dist-prod}
1274		\lean{MIPStarRE.QPBT.clDistribution_directSum_eq_prod}
1275		\leanok
1276		\uses{def:cl-dist, lem:cl-func-prod}
1277		For each $i \in \{1, \dots, m\}$ let $L^{(i)}, R^{(i)} \colon V^{(i)} \to V^{(i)}$ be $\ell_i$-level conditionally linear functions, and let $L, R \colon V \to V$ be the direct sums $L = \bigoplus_i L^{(i)}$ and $R = \bigoplus_i R^{(i)}$, as defined in Lemma~\ref{lem:cl-func-prod}. Then the conditionally linear distribution $\mu_{L,R}$ is the product distribution $\prod_{i=1}^m \mu_{L^{(i)},\,R^{(i)}}$ over $V \times V$.
1278	\end{lemma}
1279	\begin{proof}
1280		\leanok
1281		\uses{lem:cl-supported-vanishing, lem:cl-supported-restriction, lem:cl-restriction-sum}
